#!/usr/bin/env node
/**
 * Render the evidence matrix declared by config/institutional-surfaces.json.
 *
 * Usage:
 *   node scripts/screenshot-institutional.js
 *   node scripts/screenshot-institutional.js vextreme-home
 *
 * Output:
 *   docs/screenshots/{slug}-{locale}-{theme}-{viewport}.png
 *
 * This harness drives the real standalone page. It does not inject strings or
 * duplicate the registry's page, locale, theme, or viewport lists.
 *
 * LATTICE:BEGIN — generated by lib/build-lattice-headers.js from docs/lattice-map.json. Do not hand-edit; edit the JSON and regenerate.
 *   role      : registry-driven Playwright renderer for exact institutional locale/theme/viewport evidence cells
 *   reads     : config/institutional-surfaces.json (active slugs and declared evidence matrix)
 *               lib/check-institutional-surfaces.js (surfacesByState; no second lifecycle list)
 *               lib/screenshot-evidence.js (canonical matrix filename)
 *               pages/{active institutional slug}.html (rendered through a bounded local server)
 *               styles and widgets loaded by each active page
 *   writes    : docs/screenshots/{slug}-{locale}-{theme}-{viewport}.png
 *   loaded-by : package.json (institutional-surfaces:screenshots script)
 *               manual visual-evidence regeneration before institutional review
 *   tested-by : lib/check-institutional-surfaces.js (exact output-matrix completeness)
 *               review-time browser execution and visual inspection
 *
 *   CHANGE MAP — if you touch X here, also check:
 *     matrix dimensions or lifecycle selection change:
 *       - config/institutional-surfaces.json (the only authored matrix and lifecycle source)
 *       - lib/check-institutional-surfaces.js (activation acceptance)
 *       - lib/screenshot-evidence.js (filename grammar)
 *     institutional runtime controls change:
 *       - widgets/vex-institutional.js
 *       - pages/{active institutional slug}.html
 *       - lib/check-institutional-surfaces.js behavioral runtime probe
 * LATTICE:END
 */

'use strict';

const fs = require('fs');
const http = require('http');
const path = require('path');

const { surfacesByState } = require('../lib/check-institutional-surfaces');
const { evidenceFilename } = require('../lib/screenshot-evidence');

const ROOT = path.join(__dirname, '..');
const OUT_DIR = path.join(ROOT, 'docs', 'screenshots');
const REGISTRY_PATH = path.join(ROOT, 'config', 'institutional-surfaces.json');
const MIME = {
  '.css': 'text/css; charset=utf-8',
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.svg': 'image/svg+xml',
  '.webp': 'image/webp',
};

function loadPlaywright() {
  if (process.env.VEX_PLAYWRIGHT_PATH) return require(process.env.VEX_PLAYWRIGHT_PATH);
  return require('playwright');
}

function readActiveSurfaces() {
  const registry = JSON.parse(fs.readFileSync(REGISTRY_PATH, 'utf8'));
  return surfacesByState(registry, 'active');
}

function mimeFor(filePath) {
  return MIME[path.extname(filePath).toLowerCase()] || 'application/octet-stream';
}

function startServer() {
  return new Promise((resolve, reject) => {
    const server = http.createServer((request, response) => {
      let pathname;
      try {
        pathname = decodeURIComponent(new URL(request.url, 'http://127.0.0.1').pathname);
      } catch (error) {
        response.writeHead(400).end('Bad request');
        return;
      }

      const filePath = path.resolve(ROOT, `.${pathname}`);
      if (filePath !== ROOT && !filePath.startsWith(`${ROOT}${path.sep}`)) {
        response.writeHead(403).end('Forbidden');
        return;
      }

      fs.readFile(filePath, (error, data) => {
        if (error) {
          response.writeHead(error.code === 'ENOENT' ? 404 : 500).end('Not found');
          return;
        }
        response.writeHead(200, { 'Content-Type': mimeFor(filePath) });
        response.end(data);
      });
    });
    server.once('error', reject);
    server.listen(0, '127.0.0.1', () => resolve({ server, port: server.address().port }));
  });
}

async function settlePage(page) {
  await page.evaluate(async () => {
    if (document.fonts && document.fonts.ready) await document.fonts.ready;
    for (let y = 0; y < document.documentElement.scrollHeight; y += window.innerHeight) {
      window.scrollTo(0, y);
      await new Promise(resolve => setTimeout(resolve, 30));
    }
    window.scrollTo(0, 0);
    await Promise.all(Array.from(document.images).map(image => {
      if (image.complete) return Promise.resolve();
      return new Promise(resolve => {
        image.addEventListener('load', resolve, { once: true });
        image.addEventListener('error', resolve, { once: true });
      });
    }));
  });
  await page.waitForTimeout(80);
}

async function selectLocale(page, locale) {
  if (locale === 'en') {
    await page.waitForFunction(() => document.documentElement.lang === 'en');
    return;
  }
  const selector = '[data-vex-lang-select]';
  if (await page.locator(selector).count() !== 1) {
    throw new Error(`cannot operate locale ${locale}: ${selector} is absent or duplicated`);
  }
  await page.selectOption(selector, locale);
  await page.waitForFunction(expected => document.documentElement.lang === expected, locale);
}

async function verifyContract(page, surface, locale, theme, viewport) {
  const result = await page.evaluate(({ expected, locale, theme, viewport }) => {
    const html = document.documentElement;
    const width = window.innerWidth;
    return {
      surface: html.dataset.vexSurface,
      category: html.dataset.vexStringCategory,
      scope: html.dataset.vexStringScope,
      family: html.dataset.vexThemeFamily,
      theme: html.dataset.theme,
      locale: html.lang,
      horizontalOverflow: Math.max(html.scrollWidth, document.body.scrollWidth) - width,
      dimensions: {
        inner: window.innerWidth,
        htmlClient: html.clientWidth,
        htmlScroll: html.scrollWidth,
        bodyClient: document.body.clientWidth,
        bodyScroll: document.body.scrollWidth,
      },
      overflowing: Array.from(document.querySelectorAll('body *'))
        .filter(element => element.getBoundingClientRect().right > width + 1 || element.scrollWidth > element.clientWidth + 1)
        .slice(0, 5)
        .map(element => {
          const rect = element.getBoundingClientRect();
          return `${element.tagName.toLowerCase()}.${String(element.className || '').trim().replace(/\s+/g, '.')}@${Math.round(rect.right)}:${element.clientWidth}/${element.scrollWidth}`;
        }),
      viewportMatches: width === viewport,
      title: document.title,
      mainCount: document.querySelectorAll('main').length,
      h1Count: document.querySelectorAll('h1').length,
      expected,
    };
  }, {
    expected: {
      surface: surface.kind,
      category: surface.strings.category,
      scope: surface.strings.scope,
      family: surface.theme.family,
    },
    locale,
    theme,
    viewport,
  });

  const problems = [];
  for (const key of ['surface', 'category', 'scope', 'family']) {
    if (result[key] !== result.expected[key]) problems.push(`${key}=${result[key] || '(missing)'}`);
  }
  if (result.theme !== theme) problems.push(`theme=${result.theme || '(missing)'}`);
  if (result.locale !== locale) problems.push(`lang=${result.locale || '(missing)'}`);
  if (!result.viewportMatches) problems.push(`layout viewport does not equal ${viewport}px`);
  if (result.horizontalOverflow > 1) {
    problems.push(`horizontal overflow=${result.horizontalOverflow}px ${JSON.stringify(result.dimensions)} (${result.overflowing.join(', ')})`);
  }
  if (!result.title.trim()) problems.push('document title is empty');
  if (result.mainCount !== 1) problems.push(`main count=${result.mainCount}`);
  if (result.h1Count !== 1) problems.push(`h1 count=${result.h1Count}`);
  if (problems.length) throw new Error(problems.join('; '));
}

async function verifyThemeToggle(page, initialTheme) {
  const button = page.locator('[data-vex-theme-toggle]');
  if (await button.count() !== 1 || !await button.isVisible()) {
    throw new Error('theme toggle is absent, duplicated, or hidden after runtime mount');
  }
  const alternate = initialTheme === 'foundation' ? 'foundation-light' : 'foundation';
  await button.click();
  await page.waitForFunction(expected => document.documentElement.dataset.theme === expected, alternate);
  await button.click();
  await page.waitForFunction(expected => document.documentElement.dataset.theme === expected, initialTheme);
}

async function verifyKeyboardEntry(page) {
  await page.evaluate(() => {
    if (document.activeElement && document.activeElement.blur) document.activeElement.blur();
    window.scrollTo(0, 0);
  });
  await page.keyboard.press('Tab');
  const result = await page.evaluate(() => {
    const active = document.activeElement;
    const rect = active ? active.getBoundingClientRect() : null;
    return {
      isSkip: Boolean(active && active.matches('.vex-skip')),
      inViewport: Boolean(rect && rect.left >= 0 && rect.top >= 0),
      label: active ? (active.getAttribute('aria-label') || active.textContent || '').trim() : '',
    };
  });
  if (!result.isSkip || !result.inViewport || !result.label) {
    throw new Error(`first keyboard focus must expose the labelled skip link: ${JSON.stringify(result)}`);
  }
}

async function verifyLocalLinks(page, baseUrl) {
  const links = await page.evaluate(() => Array.from(document.querySelectorAll('a[href]'), anchor => ({
    href: anchor.href,
    label: (anchor.getAttribute('aria-label') || anchor.textContent || '').trim(),
  })));
  const baseOrigin = new URL(baseUrl).origin;
  for (const link of links) {
    if (!link.label) throw new Error(`unlabelled link: ${link.href}`);
    const url = new URL(link.href);
    if (url.origin !== baseOrigin) continue;
    if (url.hash && url.pathname === new URL(page.url()).pathname) {
      const targetCount = await page.locator(url.hash).count();
      if (targetCount !== 1) throw new Error(`local fragment ${url.hash} resolves to ${targetCount} targets`);
      continue;
    }
    url.hash = '';
    const response = await page.request.get(url.href);
    if (!response.ok()) throw new Error(`local link ${url.pathname} returned HTTP ${response.status()}`);
  }
}

async function renderCell(browser, baseUrl, surface, locale, theme, viewport, verifyToggle) {
  const context = await browser.newContext({
    viewport: { width: viewport, height: viewport <= 320 ? 720 : 900 },
    colorScheme: theme === 'foundation-light' ? 'light' : 'dark',
  });
  await context.addInitScript(selectedTheme => {
    try { localStorage.setItem('vex-inst-theme', selectedTheme); } catch (error) {}
  }, theme);

  // Evidence must not depend on a third-party font host being reachable. The
  // page declares complete system fallbacks; an empty remote stylesheet makes
  // this bounded run exercise those fallbacks without a noisy network error.
  await context.route('https://fonts.googleapis.com/**', route => route.fulfill({
    status: 200,
    contentType: 'text/css; charset=utf-8',
    body: '',
  }));

  const page = await context.newPage();
  const runtimeErrors = [];
  page.on('pageerror', error => runtimeErrors.push(String(error)));
  page.on('console', message => {
    if (message.type() === 'error') runtimeErrors.push(message.text());
  });

  try {
    await page.goto(`${baseUrl}/pages/${surface.slug}.html`, { waitUntil: 'networkidle' });
    await selectLocale(page, locale);
    await page.waitForFunction(expected => document.documentElement.dataset.theme === expected, theme);
    if (verifyToggle) {
      await verifyKeyboardEntry(page);
      await verifyLocalLinks(page, baseUrl);
      await verifyThemeToggle(page, theme);
    }
    await settlePage(page);
    await verifyContract(page, surface, locale, theme, viewport);
    if (runtimeErrors.length) throw new Error(`runtime error(s): ${runtimeErrors.join(' | ')}`);

    const filename = evidenceFilename(surface.slug, locale, theme, viewport);
    await page.screenshot({ path: path.join(OUT_DIR, filename), fullPage: true });
    process.stdout.write(`  ${filename}\n`);
  } finally {
    await context.close();
  }
}

async function main() {
  const requestedSlug = process.argv[2] || null;
  let surfaces = readActiveSurfaces();
  if (requestedSlug) surfaces = surfaces.filter(surface => surface.slug === requestedSlug);
  if (surfaces.length === 0) {
    throw new Error(requestedSlug
      ? `${requestedSlug} is not an active institutional surface`
      : 'the registry contains no active institutional surfaces');
  }

  for (const surface of surfaces) {
    if (!fs.existsSync(path.join(ROOT, 'pages', `${surface.slug}.html`))) {
      throw new Error(`pages/${surface.slug}.html does not exist`);
    }
  }

  fs.mkdirSync(OUT_DIR, { recursive: true });
  const { chromium } = loadPlaywright();
  const { server, port } = await startServer();
  const launchOptions = { headless: true };
  if (process.env.VEX_CHROMIUM_PATH) launchOptions.executablePath = process.env.VEX_CHROMIUM_PATH;
  let browser = null;

  try {
    browser = await chromium.launch(launchOptions);
    const baseUrl = `http://127.0.0.1:${port}`;
    let toggleVerified = false;
    for (const surface of surfaces) {
      process.stdout.write(`${surface.slug}\n`);
      for (const locale of surface.strings.requiredLocales) {
        for (const theme of surface.evidence.themes) {
          for (const viewport of surface.evidence.viewports) {
            await renderCell(browser, baseUrl, surface, locale, theme, viewport, !toggleVerified);
            toggleVerified = true;
          }
        }
      }
    }
  } finally {
    if (browser) await browser.close();
    await new Promise(resolve => server.close(resolve));
  }
}

main().catch(error => {
  console.error(`[screenshot-institutional] ${error.stack || error.message}`);
  process.exitCode = 1;
});

// [VXG RealForever]
